def solve(I):
    Hh,Ww=len(I),len(I[0])
    bg=Counter(x for r in I for x in r).most_common(1)[0][0]
    O=[list(r) for r in I]
    items=sorted(set(x for r in I for x in r)-{bg})
    # templates: multicolor? use per-color largest comp
    for v in items:
        cs=comps(I,v)
        big=max(cs,key=len)
        if len(big)<2: continue
        tl=(min(y for y,x in big),min(x for y,x in big))
        h=max(y for y,x in big)-tl[0]+1; w=max(x for y,x in big)-tl[1]+1
        pat={(r-tl[0],c-tl[1]) for r,c in big}
        # anchors: singleton cells of any color adjacent to template
        anchors=set()
        for y in range(tl[0]-2, tl[0]+h+1):
            for x in range(tl[1]-2, tl[1]+w+1):
                if 0<=y<Hh and 0<=x<Ww and (y,x) not in set(big):
                    if I[y][x]!=bg and sum(abs(a-y)+abs(b-x) for a,b in big)<=1:
                        anchors.add((y,x,I[y][x]))
        if len(anchors)!=1: continue
        ay,ax,acv=next(iter(anchors))
        for my,mx,mcv in [(y,x,I[y][x]) for y in range(Hh) for x in range(Ww) if I[y][x]!=bg and (y,x) not in set(big) and len(comps(I,I[y][x]))==1]:
            if mcv!=acv: continue
            d=(my-ay, mx-ax)
            for r,c in pat:
                y2=x2=my+d[0]+r, mx+d[1]+c
                if 0<=y2<Hh and 0<=x2<Ww and I[y2][x2]==bg:
                    O[y2][x2]=v
    return O
